def fast_close_reply_only(
    agent: str,
    bus_id: int,
    text: str = "",
    *,
    to_agent: str = "worker_ant",
) -> bool:
    """ack + reply 结案；已结案则跳过。返回是否成功（含 skipped）。"""
    if bus_id <= 0:
        return False
    if bus_is_closed(agent, bus_id):
        return True

    body = text or inbox_text(agent, bus_id)
    ack_text = f"[ACK] bus#{bus_id} 收到"
    reply_text = build_reply_only_text(bus_id, body)

    try:
        if not has_ack(agent, bus_id):
            send(
                from_agent=agent,
                to_agent=to_agent,
                text=ack_text,
                reply_to_bus_id=bus_id,
                kind="ack",
            )
        if not has_reply(agent, bus_id):
            send(
                from_agent=agent,
                to_agent=to_agent,
                text=reply_text,
                reply_to_bus_id=bus_id,
                kind="reply",
            )
        append_tg_status_event(
            agent,
            {
                "type": "done",
                "bus_id": bus_id,
                "text": f"[快车道] bus#{bus_id} reply_only 已自动 ack+reply",
            },
        )
        return True
    except SystemExit:
        return False
    except Exception:
        return False

