def fast_close_reply_only(
    agent: str,
    bus_id: int,
    text: str = "",
    *,
    to_agent: str = "worker_ant",
) -> bool:
    """progress 可达回执结案；已结案则跳过。返回是否成功（含 skipped）。

    butler 会静默丢 [REPLY]/[ACK] 与 kind=reply/ack（bus#13925/#13933），
    故改 progress 直写正文，成功后本地 mark_processed。
    """
    if bus_id <= 0:
        return False
    if bus_is_closed(agent, bus_id):
        return True

    body = text or inbox_text(agent, bus_id)
    ack_text = f"bus#{bus_id} 收到"
    reply_text = build_reply_only_text(bus_id, body)

    try:
        if not has_ack(agent, bus_id) and not has_progress(agent, bus_id):
            send(
                from_agent=agent,
                to_agent=to_agent,
                text=ack_text,
                reply_to_bus_id=bus_id,
                kind="progress",
            )
        if not has_reply(agent, bus_id):
            send(
                from_agent=agent,
                to_agent=to_agent,
                text=reply_text,
                reply_to_bus_id=bus_id,
                kind="progress",
            )
            mark_processed(agent, bus_id)
        append_tg_status_event(
            agent,
            {
                "type": "done",
                "bus_id": bus_id,
                "text": f"[快车道] bus#{bus_id} reply_only 已自动 progress 结案",
            },
        )
        return True
    except SystemExit:
        return False
    except Exception:
        return False

